// Aplana la foto d'Orion a files clau-valor per a la taula historic.
// (Unic tros de codi: convertir cada entitat en una fila per atribut.)
const ts = new Date().toISOString().slice(0, 19).replace('T', ' ');
const files = [];

for (const item of $input.all()) {
  const e = item.json;
  if (!e || !e.id) continue;
  if (e.type === 'Event') continue; // el registre d'events no va a l'historic

  for (const [atribut, valor] of Object.entries(e)) {
    if (atribut === 'id' || atribut === 'type') continue;

    let valor_num = null;
    let valor_text = null;
    if (typeof valor === 'number') valor_num = valor;
    else if (typeof valor === 'boolean') valor_num = valor ? 1 : 0;
    else if (valor === null || valor === undefined) valor_text = null;
    else if (typeof valor === 'object') valor_text = JSON.stringify(valor).slice(0, 255);
    else valor_text = String(valor).slice(0, 255);

    files.push({
      json: {
        ts,
        entitat: e.id,
        tipus: e.type || null,
        atribut,
        valor_num,
        valor_text,
      },
    });
  }
}

return files;

// Regressió lineal simple (temps en segons -> capacitat_actual_kwh)
// per a estimar les hores fins que la bateria arribe a un extrem.
const CAPACITAT_MAXIMA_KWH = 62.0;

const files = $input.all().map(item => item.json);

if (files.length < 3) {
  return [];
}

const t0 = new Date(files[0].ts).getTime();
const xs = files.map(f => (new Date(f.ts).getTime() - t0) / 1000);
const ys = files.map(f => f.valor_num);
const n = xs.length;

const mitjanaX = xs.reduce((a, b) => a + b, 0) / n;
const mitjanaY = ys.reduce((a, b) => a + b, 0) / n;
const numerador = xs.reduce((suma, x, i) => suma + (x - mitjanaX) * (ys[i] - mitjanaY), 0);
const denominador = xs.reduce((suma, x) => suma + (x - mitjanaX) ** 2, 0);
const pendent = denominador === 0 ? 0 : numerador / denominador;

// Pendent 0 (plana, sense tendència): no hi ha res a predir.
if (pendent === 0) {
  return [{ json: { valor: null } }];
}

const valorActual = ys[ys.length - 1];
// Descarregant -> hores fins buida (0). Carregant -> hores fins plena.
const objectiu = pendent < 0 ? 0 : CAPACITAT_MAXIMA_KWH;
const hores = Math.abs((objectiu - valorActual) / pendent) / 3600;

return [{ json: { valor: Math.round(hores * 100) / 100 } }];
